/*
 * BENCH: Picking an object by clicking in the view
 * TIER: HIGH
 * SUBJECT: apps/desktop/src/features/objectEditing/picking.ts#pickObjectId, #toNdc
 * MEASURES: latency
 * COMPLEXITY: O(objects) for a scene of small objects; O(triangles) for the mesh under the pointer
 * INPUTS: objects 100..1600; triangles in one mesh 10k..640k (not indexed, like a scanned model);
 *         generated by fixtures/scene.fixtures.ts with seed 20260402
 * BASELINE: baselines/editor/pick.baseline.json
 * THRESHOLD: fail if median regresses >25% (and beyond 3x the baseline spread) or p95 >40%
 * EXCLUDES: pointer events, selection state updates
 * NOTES: runs on each click, not each frame, but a click on a heavy model must not stall the interface.
 *        A miss on a heavy model costs far less than a hit, because the bounding sphere rejects the ray.
 */
import { describe, it } from "vitest";
import { PerspectiveCamera, Scene, Vector2 } from "three";
import { EditorScene } from "@/features/assistant/EditorScene";
import { pickObjectId, toNdc } from "@/features/objectEditing/picking";
import { measureCases, type BenchCase } from "../../lib/harness";
import { finishWithGrowth } from "../../lib/report";
import { consume } from "../../lib/sink";
import { buildEditor, denseMesh } from "../../fixtures/scene.fixtures";

function camera(): PerspectiveCamera {
  const view = new PerspectiveCamera(45, 4 / 3, 0.1, 1000);
  view.position.set(0, 0, 6);
  view.lookAt(0, 0, 0);
  view.updateMatrixWorld(true);
  return view;
}

describe("picking", () => {
  it("finds the object under the pointer among many small objects", async () => {
    const view = camera();
    const cases: BenchCase[] = [100, 200, 400, 800, 1600].flatMap((objects) => {
      const built = buildEditor(objects);
      // The fixture's boxes all sit at the origin, so the centre of the screen always hits one.
      built.scene.updateMatrixWorld(true);
      return [
        { name: "pickObjectId (hit)", params: { objects }, run: () => consume(pickObjectId(built.editor, view, new Vector2(0, 0))?.length ?? 0) },
        { name: "pickObjectId (miss)", params: { objects }, run: () => consume(pickObjectId(built.editor, view, new Vector2(0.95, 0.95))?.length ?? 0) },
      ];
    });
    const results = await measureCases(cases);
    finishWithGrowth("editor/pick.objects", results, [
      { key: "objects", declared: 1, label: "hit", where: (result) => result.name.includes("hit") },
      // A miss is a bounding-sphere test per object, a few microseconds in all, so timer and cache noise show.
      { key: "objects", declared: 1, tolerance: 0.5, label: "miss", where: (result) => result.name.includes("miss") },
    ]);
  });

  it("finds the point on one dense mesh", async () => {
    const view = camera();
    const cases: BenchCase[] = [10_000, 40_000, 160_000, 640_000].flatMap((triangles) => {
      const scene = new Scene();
      const editor = new EditorScene(scene, "prj_bench");
      editor.importObject("dense", denseMesh(triangles));
      scene.updateMatrixWorld(true);
      return [
        { name: "pickObjectId (hit, dense mesh)", params: { triangles }, run: () => consume(pickObjectId(editor, view, new Vector2(0, 0))?.length ?? 0) },
        { name: "pickObjectId (miss, dense mesh)", params: { triangles }, run: () => consume(pickObjectId(editor, view, new Vector2(0.95, 0.95))?.length ?? 0) },
      ];
    });
    const results = await measureCases(cases);
    finishWithGrowth("editor/pick.triangles", results, [
      { key: "triangles", declared: 1, label: "hit", where: (result) => result.name.includes("hit") },
    ]);
  });

  it("converts pointer positions", async () => {
    const bounds = { left: 100, top: 50, width: 800, height: 600 };
    const results = await measureCases([
      { name: "toNdc", params: { calls: 1 }, run: () => consume(toNdc(412, 337, bounds).x) },
    ]);
    finishWithGrowth("editor/pick.ndc", results, []);
  });
});
